"""Generate AGENTS.md: a compact router so agents load bundle documents lazily."""

from __future__ import annotations

import os
from datetime import date
from pathlib import Path

from okf.bundle import Bundle, Document, as_date
from okf.report import WARNING, Issue
from okf.validate import ALLOWED_TYPES

EXPIRING_DAYS = 30

HEADER = """\
# AGENTS.md

<!-- Generated by `okf agents` from the documents' front matter. Do not edit by hand. -->

This is the router of an OKF knowledge bundle. Do not read the whole bundle:
pick the documents relevant to your task from the table and open only those.

- **Freshness**: `fresh` is within its review window; `review due` expires within {days} days;
  `stale` is past `freshness.stale_after`, so check it against its sources before relying on it.
- **Trust**: `trust.confidence` from 0.0 to 1.0 and who wrote the document (`human`, `script`, `agent`).
  When documents disagree, prefer the more confident human-verified one.
- **Sources**: each document lists its origin in `provenance.sources`; `git://path` is a file in this repository.
"""


def render_agents(bundle: Bundle, today: date, output: Path) -> tuple[str, list[Issue]]:
    """AGENTS.md text for the bundle, plus warnings about documents left out of it."""
    out_dir = output.parent
    skipped = []
    rows = []
    for doc in bundle.knowledge():
        if doc.meta is None:
            skipped.append(
                Issue(WARNING, doc.path, "frontmatter", "Left out of AGENTS.md: front matter is missing or invalid")
            )
            continue
        rows.append(doc)
    rows.sort(key=lambda doc: (_type_order(doc.get("type", "")), doc.rel))

    lines = [HEADER.format(days=EXPIRING_DAYS)]
    service = [doc for doc in bundle.documents if doc.is_service]
    if service:
        notes = {"index.md": "table of contents for humans", "log.md": "change log"}
        links = ", ".join(f"[{doc.rel}]({_link(doc, out_dir)}) ({notes[doc.rel]})" for doc in service)
        lines.append(f"Service files: {links}.\n")

    lines.append(f"## Documents ({len(rows)})\n")
    lines.append("| Document | Type | Tags | Freshness | Trust | Path |")
    lines.append("|---|---|---|---|---|---|")
    for doc in rows:
        cells = [doc.title, _text(doc.get("type", "")), _tags(doc), freshness_status(doc, today), _trust(doc)]
        cells.append(f"[{doc.rel}]({_link(doc, out_dir)})")
        lines.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
    return "\n".join(lines) + "\n", skipped


def freshness_status(doc: Document, today: date) -> str:
    stale_after = as_date(doc.get("freshness.stale_after", None))
    if stale_after is None:
        status = "unknown"
    elif stale_after < today:
        status = f"stale since {stale_after}"
    elif (stale_after - today).days <= EXPIRING_DAYS:
        status = f"review due {stale_after}"
    else:
        status = f"fresh until {stale_after}"
    lifecycle = doc.get("lifecycle.status", None)
    if isinstance(lifecycle, str) and lifecycle.strip() and lifecycle.strip().lower() != "stable":
        status = f"{lifecycle.strip()}, {status}"
    return status


def _type_order(value: object) -> int:
    return ALLOWED_TYPES.index(value) if value in ALLOWED_TYPES else len(ALLOWED_TYPES)


def _tags(doc: Document) -> str:
    tags = doc.get("tags", None)
    return ", ".join(str(tag) for tag in tags) if isinstance(tags, list) else ""


def _trust(doc: Document) -> str:
    confidence = doc.get("trust.confidence", None)
    generated = doc.get("trust.generated", None)
    parts = []
    if isinstance(confidence, (int, float)) and not isinstance(confidence, bool):
        shown = f"{float(confidence):g}"
        parts.append(shown if "." in shown or "e" in shown else shown + ".0")
    if isinstance(generated, str) and generated.strip():
        parts.append(generated.strip())
    return " ".join(parts)


def _text(value: object) -> str:
    return value if isinstance(value, str) else ""


def _link(doc: Document, out_dir: Path) -> str:
    return Path(os.path.relpath(doc.path, out_dir)).as_posix().replace(" ", "%20")


def _cell(value: str) -> str:
    return value.replace("|", "\\|").replace("\n", " ")
